from db.models import Product, Product_image
from pathlib import Path
from slugify import slugify

# ДОБАВЛЕНИЕ ВСЕЙ ПРОДУКЦИИ В БД
def allProducts(db, app):
    created = 0

    def seed_product(**data):
        data.setdefault('short_name', data['name'])
        return Product(**data)

    def addProducts(product):
        nonlocal created
        if Product.query.filter_by(slug=product.slug).first():
            return
        from web.app.validation import product_value
        for field in ('name', 'short_name', 'price', 'price_chet', 'weight', 'concept', 'category', 'descriptions', 'G'):
            setattr(product, field, product_value(field, getattr(product, field)))
        try:
            db.session.add(product)
            db.session.flush()
            directory = Path(app.static_folder) / 'image' / 'productImgs' / product.slug
            for num in range(1, 5):
                if (directory / f'img{num}.webp').is_file():
                    db.session.add(Product_image(num, product.id, f'/static/image/productImgs/{product.slug}/img{num}.webp'))
            db.session.commit()
            created += 1
        except Exception:
            db.session.rollback()
            raise

